<script setup lang="ts">
import{ref,computed,watch,onUnmounted}from'vue';import{useRoute}from'vue-router';import{ChevronRight,MapPin,UserRound,Trophy,RefreshCw,X,Share2}from'lucide-vue-next';import{elections}from'../repositories/elections';import{useElection}from'../composables/useElection';import{states,cities,summaries,loadSummaries,loadLocations}from'../composables/useLocations';import{offices,type Office,type Result,type Candidate}from'../types/election';import{number,percent,dateTime,palette}from'../utils/format';
const route=useRoute();const uf=computed(()=>String(route.query.uf||'br'));const office=computed(()=>String(route.query.cargo||'1')as Office);const city=ref<string|null>(null);const{data,loading,error,refresh,stale}=useElection(uf,city,office);const candidate=computed(()=>data.value?.candidates.find(c=>c.id===route.params.id));const selectedUF=ref(uf.value==='br'?'pr':uf.value),sort=ref('percent'),ranking=ref<{name:string;slug:string;candidate:Candidate;updatedAt:string}[]>([]),rankLoading=ref(false),done=ref(0),failed=ref(0),show=ref(20),broken=ref(false);const regional=ref<Record<string,Candidate>>({}),regionalLoading=ref(false),shareLabel=ref('Compartilhar');let epoch=0;let regionalEpoch=0;const allCities=computed(()=>cities.value.filter(c=>c.uf===selectedUF.value));const ranked=computed(()=>ranking.value.slice().sort((a,b)=>sort.value==='percent'?(b.candidate.percent??-1)-(a.candidate.percent??-1):(b.candidate.votes??-1)-(a.candidate.votes??-1)));async function stateResults(){const generation=++regionalEpoch;const candidateId=route.params.id;if(office.value!=='1')return;regionalLoading.value=true;await loadLocations();let next=0;await Promise.all(Array.from({length:3},async()=>{while(next<states.value.length&&generation===regionalEpoch){const s=states.value[next++];try{const r=await elections.result(s.uf);const c=r.candidates.find(c=>c.id===candidateId);if(c&&generation===regionalEpoch)regional.value[s.uf]=c}catch{}}}));regionalLoading.value=false}function stop(){epoch++;rankLoading.value=false}async function loadRanking(){stop();const e=epoch;ranking.value=[];done.value=0;failed.value=0;show.value=20;rankLoading.value=true;await loadLocations();let cursor=0;const list=allCities.value.slice();await Promise.all(Array.from({length:3},async()=>{while(cursor<list.length&&e===epoch){const c=list[cursor++];try{const r=await elections.result(selectedUF.value,c.slug,office.value);if(e!==epoch)return;const found=r.candidates.find(x=>x.id===route.params.id);if(found)ranking.value.push({name:c.name,slug:c.slug,candidate:found,updatedAt:r.updatedAt})}catch{if(e===epoch)failed.value++}if(e===epoch)done.value++}}));if(e===epoch)rankLoading.value=false}watch(selectedUF,()=>{stop();ranking.value=[];done.value=0;failed.value=0});watch(()=>route.params.id,()=>{stop();ranking.value=[];regional.value={};broken.value=false;void stateResults()},{immediate:true});watch(candidate,c=>{if(c)document.title=`${c.name} • Eleições 2026 | Apura PT`});onUnmounted(()=>{stop();regionalEpoch++});async function share(){try{await navigator.clipboard.writeText(location.href);shareLabel.value='Link copiado'}catch{shareLabel.value='Copie a URL do navegador'}}
</script>
<template><main class="container candidate-page"><div class="breadcrumb"><RouterLink to="/brasil">Brasil</RouterLink><ChevronRight :size="13"/><span>Candidato</span><ChevronRight :size="13"/><span>{{candidate?.name||'Resultados'}}</span></div><div v-if="loading" class="empty-page"><div class="skeleton"></div><p>Consultando candidato no TSE…</p></div><div v-else-if="!candidate" class="empty-page"><UserRound :size="35"/><h1>{{error?'Consulta indisponível':'Candidato não encontrado'}}</h1><p>{{error||'Confira o identificador e a abrangência do candidato.'}}</p><button class="primary-button" @click="refresh">Tentar novamente</button></div><template v-else><div class="candidate-profile"><div class="profile-avatar"><img v-if="!broken" :src="candidate.photo" :alt="candidate.name" @error="broken=true"><UserRound v-else :size="50"/></div><div><div class="eyebrow">{{offices.find(o=>o.id===office)?.name}} · {{uf==='br'?'BRASIL':states.find(s=>s.uf===uf)?.name}}</div><h1>{{candidate.name}}</h1><p>{{candidate.fullName}}</p><div class="profile-tags"><span>{{candidate.party}} · {{candidate.number}}</span><span>{{candidate.status}}</span></div></div><button class="share-button" @click="share"><Share2 :size="16"/>{{shareLabel}}</button></div><div v-if="error||stale" class="connection-banner">Exibindo a última leitura disponível. {{error}}</div><div class="profile-stats"><div><span>Total de votos</span><strong>{{number(candidate.votes)}}</strong></div><div><span>{{uf==='br'?'Percentual nacional':'Percentual estadual'}}</span><strong>{{percent(candidate.percent)}}</strong></div><div><span>Seções totalizadas</span><strong>{{percent(data?.stats.progress)}}</strong></div><div><span>Última atualização · Brasília</span><b>{{dateTime(data?.updatedAt)}}</b></div></div><section v-if="office==='1'" class="panel candidate-states"><div class="panel-heading"><div><h2>Resultados por estado</h2><p>Selecione uma UF para explorar os municípios</p></div><span class="small muted">{{regionalLoading?'Carregando UFs…':'Percentuais oficiais'}}</span></div><div class="state-results-grid"><button v-for="s in states" :key="s.uf" :class="{selected:selectedUF===s.uf}" @click="selectedUF=s.uf"><span>{{s.name}}<small>{{number(regional[s.uf]?.votes)}} votos</small></span><strong>{{percent(regional[s.uf]?.percent)}}</strong></button></div></section><section class="panel ranking-panel"><div class="panel-heading"><div><h2><Trophy :size="20"/> Onde o candidato recebeu mais votos</h2><p>Ranking calculado a partir dos resultados municipais oficiais</p></div></div><div class="ranking-controls"><select v-model="selectedUF" aria-label="Estado do ranking" :disabled="office!=='1'"><option v-for="s in states" :key="s.uf" :value="s.uf">{{s.name}}</option></select><div class="segmented"><button :class="{active:sort==='percent'}" @click="sort='percent'">Maior percentual</button><button :class="{active:sort==='votes'}" @click="sort='votes'">Mais votos</button></div><button v-if="!rankLoading" class="primary-button" @click="loadRanking"><RefreshCw :size="15"/>{{ranking.length?'Atualizar ranking':'Carregar ranking'}}</button><button v-else class="secondary-button" @click="stop"><X :size="15"/>Interromper</button></div><div v-if="rankLoading||done" class="rank-status" role="status">{{rankLoading?'Consultando':'Consultados'}} {{done}} de {{allCities.length}} municípios. {{failed?`${failed} consultas indisponíveis.`:''}}<strong v-if="done<allCities.length||failed"> Ranking parcial dos municípios consultados.</strong><strong v-else> Cobertura completa da UF.</strong></div><div v-if="!ranking.length" class="empty-state"><MapPin :size="30"/><h3>Explore a votação municipal</h3><p>Carregue os municípios de {{states.find(s=>s.uf===selectedUF)?.name}} para ordenar os resultados deste candidato.</p></div><RouterLink v-for="(r,i) in ranked.slice(0,show)" :key="r.slug" :to="`/estado/${selectedUF}/${r.slug}?cargo=${office}`" class="ranking-row"><span class="rank-number">{{i+1}}</span><div><strong>{{r.name}}</strong><small>{{number(r.candidate.votes)}} votos</small></div><div class="rank-bar"><span :style="{width:(r.candidate.percent||0)+'%'}"></span></div><strong>{{percent(r.candidate.percent)}}</strong><ChevronRight :size="16"/></RouterLink><button v-if="ranked.length>show" class="all-candidates" @click="show+=30">Mostrar mais municípios</button><div class="panel-footnote">A ordenação é um cálculo derivado. Os votos e percentuais vêm do TSE; consultas municipais podem ter horários distintos. Ranking atualizado sob demanda.</div></section><div class="last-updated">Última atualização: {{dateTime(data?.updatedAt)}} · Brasília <a :href="data?.source" target="_blank" rel="noopener noreferrer">Ver arquivo de origem</a></div></template></main></template>
